<template><div><DsPageHeader title="Especialidades em lote" subtitle="Aplique uma especialidade às variáveis selecionadas" icon="check2-all"/><DsPageShell><div class="grid md:grid-cols-3 gap-3"><DsInput v-model="busca" label="Buscar variável"/><DsSelect v-model="codEspecialidade" label="Especialidade"><option value="">Selecione</option><option v-for="e in especialidades" :key="e.codEspecialidade" :value="String(e.codEspecialidade)">{{ e.nome }}</option></DsSelect><DsInput v-model="descricao" label="Descrição do vínculo"/></div><DsAlert v-if="error" variant="error">{{ error }}</DsAlert><div class="max-h-[55vh] overflow-y-auto border rounded-xl mt-4"><label v-for="v in variaveis" :key="v.codVariavel" class="flex gap-2 border-b p-3"><input v-model="selecionadas" type="checkbox" :value="v.codVariavel"/><span>{{ v.nome }} <code>{{ v.variavel }}</code></span></label></div><div class="flex gap-2 mt-4"><DsButton :loading="saving" :disabled="!selecionadas.length || !codEspecialidade" @click="salvar">Aplicar a {{ selecionadas.length }}</DsButton><DsButton variant="secondary" to="/variaveis">Voltar</DsButton></div></DsPageShell></div></template>
<script setup lang="ts">import type { Especialidade, VariavelListItem } from '~/composables/useVariaveisApi';definePageMeta({layout:'default'});const api=useVariaveisApi();const swal=useSwal();const busca=ref('');const descricao=ref('');const codEspecialidade=ref('');const selecionadas=ref<number[]>([]);const variaveis=ref<VariavelListItem[]>([]);const especialidades=ref<Especialidade[]>([]);const saving=ref(false);const error=ref('');async function load(){try{const [vars,esp]=await Promise.all([api.listVariaveis({take:500,search:busca.value}),api.getEspecialidades(0)]);variaveis.value=vars.data||[];especialidades.value=esp.data.disponiveis||[]}catch(e){error.value=e instanceof Error?e.message:'Erro'}}async function salvar(){saving.value=true;try{await api.setEspecialidadesLote({codEspecialidade:Number(codEspecialidade.value),descricao:descricao.value,variaveis:selecionadas.value});await swal.toast('Especialidades vinculadas.');selecionadas.value=[]}catch(e){await swal.toast(e instanceof Error?e.message:'Erro','error')}finally{saving.value=false}}watch(busca,()=>load());onMounted(load)</script>
